"use client"

/**
 * Row Actions (Notchset) v1.0.0 · Notchset
 * Docs: https://notchset.dev/components/row-actions
 * MIT licensed: free to use, change and share.
 */

import * as React from "react"

import { cn } from "@/lib/utils"
import { Collapse } from "@/lib/notchset/collapse"
import { NumberFlow } from "@/lib/notchset/number-flow"
import { RollingLabel } from "@/lib/notchset/shared"
import { useSound } from "@/lib/notchset/sound"

/*
 * Row Actions: an inbox whose actions wait until you reach for a row. Hover or focus slides the time up
 * and away as Archive, Snooze and Read slide in one after another. Snooze opens a row of choices inside
 * the row; picking one, or archiving, slides the row out and folds it, and the footer offers Undo.
 */

interface InboxRow {
  id: string
  name: string
  subject: string
  time: string
  avatar?: string | undefined
  unread?: boolean | undefined
}

interface RowActionsProps extends Omit<React.ComponentPropsWithoutRef<"div">, "title"> {
  title?: React.ReactNode | undefined
  rows: readonly InboxRow[]
  onArchive: (row: InboxRow) => void
  onSnooze: (row: InboxRow, until: string) => void
  onToggleRead: (row: InboxRow) => void
  /** Put a removed row back at its index. */
  onUndo?: ((row: InboxRow, index: number) => void) | undefined
  snoozeOptions?: readonly string[] | undefined
  sound?: boolean | undefined
}

const ICONS = {
  archive: ["M3 4h18v4H3z", "M5 8v11a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8", "M10 12h4"],
  snooze: ["M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18", "M12 7v5l3 2"],
  read: ["M22 12h-6l-2 3h-4l-2-3H2", "M5.5 5.1 2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.5-6.9A2 2 0 0 0 16.8 4H7.2a2 2 0 0 0-1.7 1.1Z"],
}
function Icon({ d }: { d: string[] }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className="size-[15px]" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      {d.map((p) => (
        <path key={p} d={p} />
      ))}
    </svg>
  )
}

const RowActions = React.forwardRef<HTMLDivElement, RowActionsProps>(function RowActions(
  { title = "Inbox", rows, onArchive, onSnooze, onToggleRead, onUndo, snoozeOptions = ["Later today · 6 pm", "Tomorrow · 9 am", "Next week"], sound = true, className, ...props },
  ref
) {
  const { sfx } = useSound(sound)
  const [hover, setHover] = React.useState<string | null>(null)
  const [snooze, setSnooze] = React.useState<string | null>(null)
  const [leaving, setLeaving] = React.useState<Record<string, "start" | "end">>({})
  const [toast, setToast] = React.useState<{ text: string; row: InboxRow; index: number; n: number } | null>(null)
  const timers = React.useRef<number[]>([])
  React.useEffect(() => () => timers.current.forEach((t) => window.clearTimeout(t)), [])
  React.useEffect(() => {
    if (!toast) return
    const t = window.setTimeout(() => setToast(null), 4200)
    return () => window.clearTimeout(t)
  }, [toast])
  const unread = rows.filter((r) => r.unread && !leaving[r.id]).length

  const remove = (row: InboxRow, dir: "start" | "end", text: string, done: () => void) => {
    const index = rows.findIndex((r) => r.id === row.id)
    sfx.noise(0.22, 0.035, 900, 2600)
    setLeaving((l) => ({ ...l, [row.id]: dir }))
    setSnooze(null)
    setHover(null)
    timers.current.push(
      window.setTimeout(() => {
        done()
        setLeaving(({ [row.id]: _, ...rest }) => rest)
        setToast((t) => ({ text, row, index, n: (t?.n ?? 0) + 1 }))
      }, 750)
    )
  }

  return (
    <div ref={ref} data-slot="row-actions" data-notchset="" className={cn("w-full max-w-[470px] overflow-hidden rounded-[20px] border border-[var(--border)] bg-[var(--background)] text-[var(--foreground)]", className)} {...props}>
      <div className="flex h-[52px] items-center justify-between px-4">
        <span className="text-[15px] font-semibold tracking-[-0.02em]">{title}</span>
        <span className="flex items-center gap-1.5 font-mono text-[11px] text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]">
          <span aria-hidden="true" className="size-[7px] rounded-full bg-[var(--info,var(--chart-1))]" />
          <NumberFlow value={unread} /> unread
        </span>
      </div>
      <ul className="m-0 list-none p-0">
        {rows.map((r) => {
          const gone = leaving[r.id]
          const show = !gone && (hover === r.id || snooze === r.id)
          const sz = snooze === r.id
          return (
            <li key={r.id}>
              <Collapse open={!gone} delay={gone ? 300 : 0}>
                <div
                  onMouseEnter={() => setHover(r.id)}
                  onMouseLeave={() => setHover((h) => (h === r.id && snooze !== r.id ? null : h))}
                  onFocus={() => setHover(r.id)}
                  onBlur={(e) => {
                    if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setHover((h) => (h === r.id && snooze !== r.id ? null : h))
                  }}
                  className="border-t border-[var(--border)] [transition:background-color_.2s,translate_.4s_cubic-bezier(.5,0,.75,.4),opacity_var(--ns-time-state)]"
                  style={{ background: show ? "var(--accent)" : "transparent", translate: gone === "end" ? "60px 0" : gone === "start" ? "-60px 0" : "0 0", opacity: gone ? 0 : 1 }}
                >
                  <div className="flex h-[62px] items-center gap-3 ps-3 pe-2.5">
                    <span aria-hidden="true" className={cn("size-[7px] shrink-0 rounded-full bg-[var(--info,var(--chart-1))] [transition:scale_.4s_cubic-bezier(.2,1.7,.4,1)]", r.unread ? "scale-100" : "scale-0")} />
                    <span aria-hidden="true" className="size-[34px] shrink-0 rounded-full bg-[var(--muted)] bg-cover bg-center shadow-[0_0_0_1px_var(--border)]" style={r.avatar ? { backgroundImage: `url(${r.avatar})` } : undefined} />
                    <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                      <span className={cn("text-[13.5px] whitespace-nowrap", r.unread ? "font-[650]" : "font-medium")}>
                        {r.name}
                        <span className="sr-only">{r.unread ? ", unread" : ""}</span>
                      </span>
                      <span className="truncate text-[length:var(--ns-type-label)] text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]">{r.subject}</span>
                    </span>
                    <span className="relative h-[34px] w-[110px] shrink-0">
                      <span className="absolute end-1.5 top-0 flex h-[34px] items-center font-mono text-[11px] whitespace-nowrap [transition:opacity_.2s,translate_.35s_cubic-bezier(.2,1.2,.3,1)] text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]" style={{ opacity: show ? 0 : 1, translate: show ? "0 -10px" : "0 0" }}>
                        {r.time}
                      </span>
                      <span className={cn("absolute end-0 top-0 flex gap-1", !show && "pointer-events-none")}>
                        {(["archive", "snooze", "read"] as const).map((k, i) => (
                          <button
                            key={k}
                            type="button"
                            aria-label={k === "archive" ? `Archive ${r.name}` : k === "snooze" ? `Snooze ${r.name}` : r.unread ? `Mark ${r.name} read` : `Mark ${r.name} unread`}
                            aria-expanded={k === "snooze" ? sz : undefined}
                            title={k === "archive" ? "Archive" : k === "snooze" ? "Snooze" : "Toggle read"}
                            onClick={() => {
                              if (k === "archive") remove(r, "end", `Archived · ${r.name}`, () => onArchive(r))
                              else if (k === "snooze") {
                                if (sz) sfx.close()
                                else sfx.open()
                                setSnooze(sz ? null : r.id)
                                setHover(r.id)
                              } else {
                                if (r.unread) sfx.tick()
                                else sfx.pop()
                                onToggleRead(r)
                              }
                            }}
                            className={cn("grid size-[34px] shrink-0 cursor-pointer place-items-center rounded-full outline-none [transition:opacity_.25s,translate_.45s_cubic-bezier(.2,1.4,.3,1),scale_.45s_cubic-bezier(.2,1.4,.3,1),background-color_.2s] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] motion-reduce:transition-none", k === "snooze" && sz ? "bg-[var(--foreground)] text-[var(--background)]" : "hover:bg-[color-mix(in_oklab,var(--foreground)_8%,transparent)]")}
                            style={{ opacity: show ? 1 : 0, translate: show ? "0 0" : `${12 + (2 - i) * 6}px 0`, scale: show ? "1" : ".7", transitionDelay: show ? `${i * 40}ms` : "0ms" }}
                          >
                            <Icon d={ICONS[k]} />
                          </button>
                        ))}
                      </span>
                    </span>
                  </div>
                  <Collapse open={sz}>
                    <div className="flex flex-wrap gap-1.5 ps-[65px] pe-3 pb-3.5">
                      {snoozeOptions.map((o, i) => (
                        <button
                          key={o}
                          type="button"
                          onClick={() => remove(r, "start", `Snoozed · ${o}`, () => onSnooze(r, o))}
                          className="h-[30px] cursor-pointer rounded-full border border-[var(--border)] bg-[var(--background)] px-[var(--ns-inset-compact)] text-[12.5px] font-medium whitespace-nowrap outline-none [transition:opacity_.25s,scale_.45s_var(--ns-ease-rebound),background-color_.2s] hover:bg-[var(--accent)] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))]"
                          style={{ opacity: sz ? 1 : 0, scale: sz ? "1" : ".7", transitionDelay: `${80 + i * 50}ms` }}
                        >
                          {o}
                        </button>
                      ))}
                    </div>
                  </Collapse>
                </div>
              </Collapse>
            </li>
          )
        })}
      </ul>
      <div className="flex h-12 items-center justify-between gap-2 border-t border-[var(--border)] ps-4 pe-2">
        <span role="status" className="min-w-0 text-[12.5px] text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]">
          <RollingLabel index={toast ? 1 : 0} align="start" rows={["Hover or focus a row for its actions", <span key={toast?.n ?? 0} className="truncate text-[var(--foreground)]">✓ {toast?.text}</span>]} />
        </span>
        {onUndo && (
          <button
            type="button"
            tabIndex={toast ? 0 : -1}
            onClick={() => {
              if (!toast) return
              sfx.pop()
              onUndo(toast.row, toast.index)
              setToast(null)
            }}
            className={cn("h-[30px] shrink-0 cursor-pointer rounded-full bg-[var(--foreground)] px-[var(--ns-inset-compact)] text-[length:var(--ns-type-note)] font-medium text-[var(--background)] outline-none [transition:opacity_.25s,scale_.4s_var(--ns-ease-rebound)] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))]", toast ? "scale-100 opacity-100" : "pointer-events-none scale-[.7] opacity-0")}
          >
            Undo
          </button>
        )}
      </div>
    </div>
  )
})

export { RowActions, type InboxRow, type RowActionsProps }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { inertRef } from "@/lib/notchset/shared"

/*
 * The disclosure parts every accordion shares: Collapse animates height with grid rows (0fr ↔ 1fr, .5s)
 * and makes closed content inert; accordionKeys moves focus between a container's triggers with ↑/↓,
 * Home and End, as the WAI-ARIA accordion pattern asks.
 */

interface CollapseProps extends React.ComponentPropsWithoutRef<"div"> {
  open: boolean
  /** Delay before the height moves, ms (for cascades). */
  delay?: number | undefined
  /** The trigger's id, for the region's name. */
  labelledBy?: string | undefined
}

function Collapse({ open, delay = 0, labelledBy, className, style, children, ...props }: CollapseProps) {
  return (
    <div
      role={labelledBy ? "region" : undefined}
      aria-labelledby={labelledBy}
      className={cn("grid [transition:grid-template-rows_.5s_var(--ns-ease-settle)] motion-reduce:transition-none", open ? "grid-rows-[1fr]" : "grid-rows-[0fr]", className)}
      style={{ transitionDelay: delay ? `${delay}ms` : undefined, ...style }}
      {...props}
    >
      <div ref={inertRef(!open)} className="min-h-0 overflow-hidden">
        {children}
      </div>
    </div>
  )
}

/** On an accordion's container: ↑/↓ move between its [data-accordion-trigger] buttons, Home and End jump. */
function accordionKeys(event: React.KeyboardEvent<HTMLElement>) {
  if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return
  const own = Array.from(event.currentTarget.querySelectorAll<HTMLElement>("[data-accordion-trigger]")).filter((el) => el.closest("[inert]") === null)
  const at = own.indexOf(document.activeElement as HTMLElement)
  if (at < 0) return
  event.preventDefault()
  const next = event.key === "Home" ? 0 : event.key === "End" ? own.length - 1 : (at + (event.key === "ArrowDown" ? 1 : -1) + own.length) % own.length
  own[next]?.focus()
}

/** One-open or many-open state for a list of ids, controlled or not. */
function useOpenSet({ type, value, defaultValue = [], onValueChange }: { type: "single" | "multiple"; value?: readonly string[] | undefined; defaultValue?: readonly string[] | undefined; onValueChange?: ((open: string[]) => void) | undefined }) {
  const [inner, setInner] = React.useState<readonly string[]>(defaultValue)
  const open = value ?? inner
  const set = (next: string[]) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  const toggle = (id: string) => {
    const on = open.includes(id)
    set(on ? open.filter((x) => x !== id) : type === "single" ? [id] : [...open, id])
    return !on
  }
  return { open, toggle, set }
}

export { accordionKeys, Collapse, useOpenSet, type CollapseProps }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * NumberFlow: the fluid number every changing figure renders through (countdowns, times, counts, totals).
 * Each digit is its own 0–9 column that springs to the new digit with a slight motion blur; digits that
 * appear or disappear animate their width, so the text never jumps. Other characters (":", ",", " ")
 * swap in place. Screen readers get the plain value.
 */

const H = 1.15 // em, one digit row

function Digit({ d, enter, tight }: { d: number; enter: boolean; tight?: boolean | undefined }) {
  // Each change flips between two identical blur keyframes, so the blur restarts every time.
  const [seen, setSeen] = React.useState(d)
  const [flips, setFlips] = React.useState(0)
  if (seen !== d) {
    setSeen(d)
    setFlips((n) => n + 1)
  }
  return (
    <span
      aria-hidden="true"
      className={cn(
        "relative inline-block [clip-path:inset(0_-0.15em)]",
        // Tight digits are narrower than their glyphs: they clip only up and down (the clip-path bounds the sides), so a 1 isn't cut.
        tight ? "[overflow-x:visible] [overflow-y:clip] transition-[width] duration-[.55s] ease-[var(--ns-ease-settle)] motion-reduce:transition-none" : "w-[1ch] overflow-hidden",
        enter && "animate-[ns-num-in_.55s_var(--ns-ease-settle)_both] motion-reduce:animate-none"
      )}
      // Tight digits: a 1 is narrower than the rest, as in a headline price.
      style={{ height: `${H}em`, lineHeight: `${H}em`, width: tight ? (d === 1 ? "0.43em" : "0.58em") : undefined }}
    >
      <span
        className={cn(
          "flex flex-col",
          // Tight: each glyph keeps a box as wide as itself, centred in the narrower slot.
          tight && "items-center",
          "[transition:transform_.85s_var(--ns-ease-settle),scale_.85s_var(--ns-ease-settle),translate_.85s_var(--ns-ease-settle),rotate_.85s_var(--ns-ease-settle)] motion-reduce:transition-none",
          flips > 0 && (flips % 2 ? "animate-[ns-num-blur_.45s_ease-out]" : "animate-[ns-num-blur-b_.45s_ease-out]")
        )}
        style={{ transform: `translateY(${-d * H}em)` }}
      >
        {Array.from({ length: 10 }, (_, i) => (
          <span key={i} className={cn("block text-center", tight && "w-[0.76em] shrink-0")} style={{ height: `${H}em` }}>
            {i}
          </span>
        ))}
      </span>
    </span>
  )
}

interface NumberFlowProps extends Omit<React.ComponentPropsWithoutRef<"span">, "children"> {
  /** The value as it should read, e.g. 42, "09:30" or "1,204". */
  value: string | number
  /** Proportional digit widths (a 1 is 0.43em, the rest 0.58em), for large headline figures. */
  tight?: boolean | undefined
}

const NumberFlow = React.forwardRef<HTMLSpanElement, NumberFlowProps>(function NumberFlow({ value, tight, className, ...props }, ref) {
  const text = String(value)
  const chars = Array.from(text)
  // Positions are counted from the right, so the ones digit stays the ones digit when the length changes.
  const [initialLength] = React.useState(chars.length)
  const [prev, setPrev] = React.useState(text)
  const [leaving, setLeaving] = React.useState<{ id: string; ch: string }[]>([])
  if (prev !== text) {
    const old = Array.from(prev)
    if (old.length > chars.length) {
      const gone = old.slice(0, old.length - chars.length).filter((ch) => ch >= "0" && ch <= "9")
      setLeaving((l) => [...l, ...gone.map((ch, i) => ({ id: `${prev}>${text}:${i}`, ch }))].slice(-4))
    }
    setPrev(text)
  }

  return (
    <span ref={ref} data-slot="number-flow" className={cn("inline-flex whitespace-nowrap tabular-nums", className)} {...props}>
      <span className="sr-only">{text}</span>
      {leaving.map((g) => (
        <span
          key={`out-${g.id}`}
          aria-hidden="true"
          className="inline-block w-0 animate-[ns-num-out_.45s_var(--ns-ease-settle)_both] overflow-hidden text-center"
          style={{ height: `${H}em`, lineHeight: `${H}em` }}
          onAnimationEnd={() => setLeaving((l) => l.filter((x) => x.id !== g.id))}
        >
          {g.ch}
        </span>
      ))}
      {chars.map((ch, i) => {
        const pos = chars.length - i
        return ch >= "0" && ch <= "9" ? (
          <Digit key={`d${pos}`} d={Number(ch)} enter={pos > initialLength} tight={tight} />
        ) : (
          <span key={`s${pos}`} aria-hidden="true" className="inline-block whitespace-pre" style={{ height: `${H}em`, lineHeight: `${H}em` }}>
            {ch}
          </span>
        )
      })}
    </span>
  )
})

export { NumberFlow, type NumberFlowProps }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * The shared parts: the rolling label every state change goes through, the check that draws
 * itself, the spinner and the live dot, and a timeline that schedules a component's steps and clears
 * them when it unmounts. Every class string is a plain literal (the shadcn CLI only rewrites those for
 * apps with tailwind.prefix). Keyframes (ns-*) live in the foundation CSS.
 *
 * Easing vocabulary (the design's names): press var(--ns-ease-press) for scale on press; roll
 * var(--ns-ease-reshape) for label rolls, menus and width morphs; pop var(--ns-ease-pop) for
 * icon swaps and checks landing; draw cubic-bezier(.6,0,.2,1) for strokes and sweeps; exit
 * cubic-bezier(.6,0,.9,.5) for things leaving.
 */

/** Runs on the client before paint, and as an effect on the server (React 18 warns about layout effects there). */
const useIsomorphicLayoutEffect = typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

/** Points one ref (callback or object) at `node`. */
function assignRef<T>(ref: React.Ref<T> | undefined, node: T | null) {
  if (typeof ref === "function") ref(node)
  else if (ref) (ref as React.MutableRefObject<T | null>).current = node
}

/** Sets every ref passed (callback or object), so a component can keep its own ref and forward the caller's. */
function useComposedRefs<T>(...refs: (React.Ref<T> | undefined)[]) {
  const latest = React.useRef(refs)
  useIsomorphicLayoutEffect(() => {
    latest.current = refs
  })
  return React.useCallback((node: T | null) => {
    for (const ref of latest.current) assignRef(ref, node)
  }, [])
}

/** Schedules a component's steps; every pending step is cleared on clear() and on unmount. */
function useTimeline() {
  const timers = React.useRef<Set<ReturnType<typeof setTimeout>>>(new Set())
  React.useEffect(() => {
    const set = timers.current
    return () => {
      for (const t of set) clearTimeout(t)
      set.clear()
    }
  }, [])
  return React.useMemo(
    () => ({
      after(ms: number, fn: () => void) {
        const t = setTimeout(() => {
          timers.current.delete(t)
          fn()
        }, ms)
        timers.current.add(t)
        return t
      },
      clear() {
        for (const t of timers.current) clearTimeout(t)
        timers.current.clear()
      },
    }),
    []
  )
}

/** Resolves after `ms` (a minimum time a state shows, so a fast promise still reads). */
const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

/**
 * A fixed-height window over a stack of rows; row `index` shows, the others roll past (.5s roll). Only
 * the showing row is in the accessibility tree, so the button's name is always the current label.
 */
function RollingLabel({ rows, index, size = "default", align = "center", fit = false, rowHeight, className }: { rows: readonly React.ReactNode[]; index: number; size?: "default" | "sm" | undefined; align?: "center" | "start" | undefined; /** Rows as wide as their own text (inside a window sized to the active row). */ fit?: boolean | undefined; /** A row height in px, for titles (overrides size). */ rowHeight?: number | undefined; className?: string | undefined }) {
  const height = rowHeight ?? (size === "sm" ? 18 : 20)
  return (
    <span data-slot="rolling-label" className={cn("relative block overflow-hidden", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), className)} style={rowHeight ? { height: rowHeight } : undefined}>
      <span
        className={cn("flex flex-col transition-transform duration-500 ease-[var(--ns-ease-reshape)] motion-reduce:transition-none", fit && (align === "center" ? "items-center" : "items-start"))}
        style={{ transform: `translateY(${-index * height}px)` }}
      >
        {rows.map((row, i) => (
          <span
            key={i}
            aria-hidden={i === index ? undefined : true}
            className={cn("flex shrink-0 items-center gap-2 whitespace-nowrap", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), align === "center" ? "justify-center" : "justify-start", fit && "w-max")}
            style={rowHeight ? { height: rowHeight, lineHeight: `${rowHeight}px` } : undefined}
          >
            {row}
          </span>
        ))}
      </span>
    </span>
  )
}

/** The check that draws itself in (.45s draw after .15s) when `shown`. */
function DrawCheck({ shown, className }: { shown: boolean; className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-4 shrink-0", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
      <path
        d="M20 6 9 17l-5-5"
